-- Daily Signal schema v1.0 | PostgreSQL 17+
-- Design reference for Alembic migrations; production schema must be managed by Alembic.
-- UUIDs are generated by the application. All timestamp columns use UTC-aware TIMESTAMPTZ.

CREATE TABLE publisher_groups (
    id UUID PRIMARY KEY,
    slug TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    country_code CHAR(2) NOT NULL
);

CREATE TABLE news_sources (
    id UUID PRIMARY KEY,
    publisher_group_id UUID NOT NULL REFERENCES publisher_groups(id),
    slug TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    homepage_url TEXT NOT NULL,
    source_type TEXT NOT NULL CHECK (source_type IN ('editorial', 'primary')),
    origin_country CHAR(2) NOT NULL,
    primary_language TEXT NOT NULL,
    review_status TEXT NOT NULL DEFAULT 'in_review'
        CHECK (review_status IN ('candidate', 'in_review', 'approved', 'suspended', 'rejected')),
    enabled BOOLEAN NOT NULL DEFAULT FALSE,
    reviewed_at TIMESTAMPTZ,
    next_review_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT source_enable_requires_approval CHECK (NOT enabled OR review_status = 'approved')
);

CREATE TABLE source_feeds (
    id UUID PRIMARY KEY,
    source_id UUID NOT NULL REFERENCES news_sources(id),
    feed_url TEXT NOT NULL UNIQUE,
    feed_kind TEXT NOT NULL DEFAULT 'rss' CHECK (feed_kind IN ('rss', 'atom', 'api')),
    enabled BOOLEAN NOT NULL DEFAULT FALSE,
    poll_interval_minutes INTEGER NOT NULL DEFAULT 30 CHECK (poll_interval_minutes >= 15),
    etag TEXT,
    http_last_modified TEXT,
    last_checked_at TIMESTAMPTZ,
    last_success_at TIMESTAMPTZ,
    consecutive_errors INTEGER NOT NULL DEFAULT 0 CHECK (consecutive_errors >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, source_id)
);

CREATE TABLE source_permissions (
    id UUID PRIMARY KEY,
    source_id UUID NOT NULL REFERENCES news_sources(id),
    revision INTEGER NOT NULL CHECK (revision > 0),
    review_status TEXT NOT NULL DEFAULT 'in_review'
        CHECK (review_status IN ('in_review', 'approved', 'suspended', 'rejected')),
    license_code TEXT NOT NULL,
    license_url TEXT NOT NULL,
    terms_url TEXT NOT NULL,
    evidence_url TEXT,
    content_scope TEXT NOT NULL,
    attribution_requirements TEXT NOT NULL,
    retention_hours INTEGER CHECK (retention_hours > 0),
    fetch_metadata BOOLEAN NOT NULL DEFAULT FALSE,
    fetch_full_text BOOLEAN NOT NULL DEFAULT FALSE,
    analyze_content BOOLEAN NOT NULL DEFAULT FALSE,
    store_temporary BOOLEAN NOT NULL DEFAULT FALSE,
    store_long_term BOOLEAN NOT NULL DEFAULT FALSE,
    send_to_external_llm BOOLEAN NOT NULL DEFAULT FALSE,
    create_embeddings BOOLEAN NOT NULL DEFAULT FALSE,
    create_adaptations BOOLEAN NOT NULL DEFAULT FALSE,
    republish_original_content BOOLEAN NOT NULL DEFAULT FALSE,
    publish_derivatives BOOLEAN NOT NULL DEFAULT FALSE,
    republish_media BOOLEAN NOT NULL DEFAULT FALSE,
    approved_by TEXT,
    approved_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (source_id, revision),
    UNIQUE (id, source_id),
    CONSTRAINT permission_approval_has_auditor CHECK (
        review_status <> 'approved' OR (approved_by IS NOT NULL AND approved_at IS NOT NULL)
    )
);

CREATE TABLE source_items (
    id UUID PRIMARY KEY,
    source_id UUID NOT NULL REFERENCES news_sources(id),
    feed_id UUID NOT NULL REFERENCES source_feeds(id),
    permission_id UUID NOT NULL,
    external_id TEXT,
    original_url TEXT NOT NULL,
    canonical_url TEXT NOT NULL,
    original_title TEXT NOT NULL,
    author TEXT,
    language TEXT NOT NULL,
    published_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ,
    first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    content_checksum TEXT,
    license_code TEXT,
    license_url TEXT,
    license_verified BOOLEAN NOT NULL DEFAULT FALSE,
    contains_third_party_material BOOLEAN NOT NULL DEFAULT FALSE,
    originating_agency TEXT,
    origin_group_key TEXT,
    editorial_type TEXT NOT NULL DEFAULT 'unknown'
        CHECK (editorial_type IN ('news', 'analysis', 'opinion', 'interview', 'unknown')),
    ingestion_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (ingestion_status IN ('pending', 'accepted', 'quarantined', 'rejected')),
    FOREIGN KEY (permission_id, source_id) REFERENCES source_permissions(id, source_id),
    FOREIGN KEY (feed_id, source_id) REFERENCES source_feeds(id, source_id),
    UNIQUE (source_id, canonical_url),
    UNIQUE (id, source_id)
);

CREATE UNIQUE INDEX uq_source_items_external_id
    ON source_items (source_id, external_id) WHERE external_id IS NOT NULL;
CREATE INDEX ix_source_items_time ON source_items (published_at DESC);
CREATE INDEX ix_source_items_source_time ON source_items (source_id, published_at DESC);
CREATE INDEX ix_source_items_status ON source_items (ingestion_status);

CREATE TABLE source_item_content (
    item_id UUID PRIMARY KEY REFERENCES source_items(id) ON DELETE CASCADE,
    body_text TEXT NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    stored_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ix_source_item_content_expiry ON source_item_content (expires_at);

CREATE TABLE events (
    id UUID PRIMARY KEY,
    internal_title TEXT NOT NULL,
    event_date DATE,
    event_time_estimate TIMESTAMPTZ,
    region TEXT NOT NULL CHECK (region IN ('germany', 'europe', 'world')),
    category TEXT NOT NULL CHECK (category IN (
        'politics', 'economy', 'world', 'science', 'technology',
        'environment', 'society', 'health'
    )),
    first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE event_items (
    event_id UUID NOT NULL REFERENCES events(id) ON DELETE CASCADE,
    item_id UUID NOT NULL REFERENCES source_items(id),
    PRIMARY KEY (event_id, item_id)
);
CREATE INDEX ix_event_items_item ON event_items (item_id);

CREATE TABLE event_claims (
    id UUID PRIMARY KEY,
    event_id UUID NOT NULL REFERENCES events(id) ON DELETE CASCADE,
    claim_text TEXT NOT NULL,
    verification_status TEXT NOT NULL DEFAULT 'unverified'
        CHECK (verification_status IN ('supported', 'disputed', 'unverified')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE claim_evidence (
    claim_id UUID NOT NULL REFERENCES event_claims(id) ON DELETE CASCADE,
    item_id UUID NOT NULL REFERENCES source_items(id),
    evidence_role TEXT NOT NULL CHECK (evidence_role IN ('supports', 'contradicts', 'context')),
    PRIMARY KEY (claim_id, item_id)
);
CREATE INDEX ix_claim_evidence_item ON claim_evidence (item_id);

CREATE TABLE pipeline_runs (
    id UUID PRIMARY KEY,
    job_type TEXT NOT NULL CHECK (job_type IN ('ingestion', 'daily_analysis', 'correction', 'cleanup')),
    target_date DATE,
    status TEXT NOT NULL DEFAULT 'running'
        CHECK (status IN ('running', 'succeeded', 'failed', 'blocked')),
    started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at TIMESTAMPTZ,
    model_provider TEXT,
    model_id TEXT,
    pipeline_version TEXT NOT NULL,
    prompt_version TEXT,
    methodology_version TEXT,
    input_tokens INTEGER CHECK (input_tokens >= 0),
    output_tokens INTEGER CHECK (output_tokens >= 0),
    estimated_cost_usd NUMERIC(12, 6) CHECK (estimated_cost_usd >= 0),
    error_code TEXT,
    quality_checks JSONB NOT NULL DEFAULT '{}'::jsonb,
    CONSTRAINT pipeline_finished_if_terminated CHECK (
        status = 'running' OR finished_at IS NOT NULL
    )
);
CREATE INDEX ix_pipeline_runs_target ON pipeline_runs (target_date, started_at DESC);

-- One row per report revision. No separate report_revisions table is needed.
CREATE TABLE daily_reports (
    id UUID PRIMARY KEY,
    report_date DATE NOT NULL,
    revision INTEGER NOT NULL CHECK (revision > 0),
    status TEXT NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft', 'validated', 'published', 'withdrawn')),
    is_current BOOLEAN NOT NULL DEFAULT FALSE,
    headline TEXT,
    summary TEXT,
    score SMALLINT CHECK (score BETWEEN 1 AND 5),
    raw_score NUMERIC(5, 3) CHECK (raw_score BETWEEN -2 AND 2),
    score_label TEXT CHECK (score_label IN (
        'very_negative', 'negative', 'mixed', 'positive', 'very_positive'
    )),
    score_confidence TEXT CHECK (score_confidence IN ('high', 'medium', 'limited')),
    score_explanation TEXT,
    methodology_version TEXT NOT NULL,
    prompt_version TEXT NOT NULL,
    pipeline_run_id UUID REFERENCES pipeline_runs(id),
    published_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (report_date, revision),
    CONSTRAINT published_report_complete CHECK (
        status <> 'published' OR (
            headline IS NOT NULL AND summary IS NOT NULL AND score IS NOT NULL
            AND raw_score IS NOT NULL AND score_label IS NOT NULL
            AND score_confidence IN ('high', 'medium')
            AND score_explanation IS NOT NULL AND published_at IS NOT NULL
        )
    ),
    CONSTRAINT current_report_is_published CHECK (NOT is_current OR status = 'published')
);
CREATE UNIQUE INDEX uq_current_published_report_per_day
    ON daily_reports (report_date) WHERE is_current AND status = 'published';
CREATE INDEX ix_daily_reports_calendar ON daily_reports (report_date DESC)
    WHERE is_current AND status = 'published';

CREATE TABLE daily_report_stories (
    id UUID PRIMARY KEY,
    report_id UUID NOT NULL REFERENCES daily_reports(id) ON DELETE CASCADE,
    event_id UUID NOT NULL REFERENCES events(id),
    rank SMALLINT NOT NULL CHECK (rank BETWEEN 1 AND 8),
    title TEXT NOT NULL,
    summary TEXT NOT NULL,
    why_it_matters TEXT NOT NULL,
    category TEXT NOT NULL CHECK (category IN (
        'politics', 'economy', 'world', 'science', 'technology',
        'environment', 'society', 'health'
    )),
    region TEXT NOT NULL CHECK (region IN ('germany', 'europe', 'world')),
    direction TEXT NOT NULL CHECK (direction IN (
        'negative', 'positive', 'neutral', 'mixed', 'unknown'
    )),
    direction_value SMALLINT CHECK (direction_value BETWEEN -2 AND 2),
    impact SMALLINT NOT NULL CHECK (impact BETWEEN 1 AND 5),
    content_basis TEXT NOT NULL CHECK (content_basis IN ('facts_synthesis', 'adaptation')),
    derivative_license_code TEXT,
    derivative_license_url TEXT,
    modification_notice TEXT,
    UNIQUE (report_id, event_id),
    UNIQUE (report_id, rank),
    CONSTRAINT direction_consistent CHECK (
        (direction = 'negative' AND direction_value IN (-2, -1)) OR
        (direction = 'positive' AND direction_value IN (1, 2)) OR
        (direction = 'neutral' AND direction_value = 0) OR
        (direction IN ('mixed', 'unknown') AND direction_value IS NULL)
    ),
    CONSTRAINT adaptation_metadata_required CHECK (
        content_basis <> 'adaptation' OR
        (derivative_license_code IS NOT NULL AND derivative_license_url IS NOT NULL
         AND modification_notice IS NOT NULL)
    )
);
CREATE INDEX ix_daily_report_stories_report ON daily_report_stories (report_id, rank);

-- Snapshots make attribution stable even when an upstream article changes later.
CREATE TABLE story_sources (
    story_id UUID NOT NULL REFERENCES daily_report_stories(id) ON DELETE CASCADE,
    item_id UUID NOT NULL REFERENCES source_items(id),
    publisher_snapshot TEXT NOT NULL,
    url_snapshot TEXT NOT NULL,
    title_snapshot TEXT,
    author_snapshot TEXT,
    license_code_snapshot TEXT,
    license_url_snapshot TEXT,
    attribution_snapshot TEXT,
    origin_agency_snapshot TEXT,
    evidence_role TEXT NOT NULL CHECK (evidence_role IN ('supports', 'context')),
    content_modified BOOLEAN NOT NULL DEFAULT FALSE,
    modification_notice TEXT,
    PRIMARY KEY (story_id, item_id)
);
CREATE INDEX ix_story_sources_item ON story_sources (item_id);

-- Publication transaction, not a database CHECK, enforces:
-- 5..8 stories per report, all referenced claims supported, verified rights,
-- source independence, threshold consistency, and current-revision switch.
